// hosting_advisor's curated dataset: PG1's own compilation of public,
// factual information from official sources. Every fact carries its source
// URL and the date it was checked. The same rows are seeded into
// pg1_jurisdictions and pg1_providers (supabase/migrations/..._pg1_hosting.sql,
// generated by scripts/hosting-seed-sql.mjs); updates are researched in the
// lab and applied only after the operator approves them (/hosting apply).
//
// SEED STATUS: these seed facts were compiled from PG1's research notes, not
// re-checked live on the date below. Each is marked verified: false until
// the operator (or an approved lab update) confirms it against its source.
// Facts older than STALE_AFTER_DAYS are flagged stale in every answer.

export const STALE_AFTER_DAYS = 180;
export const SEED_CHECKED_ON = '2026-06-01';

const f = (value, source_url, extra = {}) => ({ value, source_url, checked_on: SEED_CHECKED_ON, verified: false, ...extra });

const GDPR = 'https://eur-lex.europa.eu/eli/reg/2016/679/oj';
