const EEA_GDPR = 'https://www.efta.int/eea/eea-agreement';
const OFAC_PROGRAMS = 'https://ofac.treasury.gov/sanctions-programs-and-country-information';
const EU_SANCTIONS_MAP = 'https://www.sanctionsmap.eu/';

